// Authentic APIx Prototype Dataset
export interface RouteFilter {
  code: string;
  label: string;
}

export interface DashboardKPIs {
  latestIndex: number;
  change7d: number;
  quoteCoverage: number;
  activeRoutes: number;
  latestPeriod: string;
  sampleSize: number;
}

export interface DailySeriesItem {
  periodKey: string;
  value: number;
  sampleSize: number;
  coverage: number;
  [key: string]: any;
}

export interface HeatmapItem {
  routeCode: string;
  routeLabel?: string;
  value: number;
  change?: number;
  [key: string]: any;
}

export interface ElasticityItem {
  windowDays: number;
  premiumVsT30: number;
  price: number;
  sampleSize?: number;
  [key: string]: any;
}

export interface IngestionMetrics {
  eligible: number;
  duplicateCount: number;
  outlierCount: number;
  nonAvailableCount: number;
  received?: number;
  [key: string]: any;
}

export interface DashboardData {
  filters: {
    routes: RouteFilter[];
    carriers: string[];
    bookingWindows: number[];
  };
  kpis: DashboardKPIs;
  series: {
    daily: DailySeriesItem[];
    weekly?: any[];
    monthly?: any[];
  };
  heatmap: HeatmapItem[];
  elasticity: ElasticityItem[];
  benchmark?: any[];
  ingestion: IngestionMetrics;
}

export interface RouteMetadata {
  code: string;
  origin: string;
  destination: string;
  label: string;
  basketWeight: number | string;
  baselineFare: number;
}

export interface MethodologyData {
  baseline: string;
  routeAggregation: string;
  exclusions: string;
  dataBoundary: string;
}

export interface FareQuote {
  routeCode: string;
  routeLabel: string;
  basketWeight: number;
  observedAt: string;
  departureDate: string;
  bookingWindowDays: number;
  carrier: string;
  fareClass: string;
  baseFare: number;
  taxes: number;
  totalFare: number;
  availability: string;
  sourceType: string;
  sourceReference: string;
  isDuplicate: boolean;
  isOutlier: boolean;
  normalizationNotes: string[];
}

